code='''from collections import Counter

def _components(grid, color):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            seen.add((r, c))
            stack = [(r, c)]
            pts = []
            while stack:
                x, y = stack.pop()
                pts.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (x + dx, y + dy)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p)
                        stack.append(p)
            out.append(pts)
    return out

def _normalize(points):
    mr = min(r for r, c in points)
    mc = min(c for r, c in points)
    return frozenset((r - mr, c - mc) for r, c in points)

def _orientations(points):
    shapes = set()
    for flip in (False, True):
        for turns in range(4):
            pts = []
            for r, c in points:
                x, y = r, -c if flip else c
                for _ in range(turns):
                    x, y = y, -x
                pts.append((x, y))
            shapes.add(_normalize(pts))
    return shapes

def _fits(small, large):
    large = set(large)
    for shape in _orientations(small):
        hh = max(r for r, c in shape) + 1
        ww = max(c for r, c in shape) + 1
        for dr in range(-hh + 1, hh):
            for dc in range(-ww + 1, ww):
                if {(r + dr, c + dc) for r, c in shape} <= large:
                    return True
    return False

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    objects = []
    for color in counts:
        if color == background:
            continue
        for pts in _components(grid, color):
            rs = [r for r, c in pts]
            cs = [c for r, c in pts]
            box = (max(rs) - min(rs) + 1) * (max(cs) - min(cs) + 1)
            objects.append((color, pts, box / len(pts)))
    # The sparse, extended component acts as the color/pattern key.
    keys = [o for o in objects if len(o[1]) >= 3]
    if not keys:
        return [row[:] for row in grid]
    key_color, key_pts, _ = max(keys, key=lambda o: (o[2], len(o[1])))
    candidates = []
    for color, pts, _ in objects:
        if color == key_color or len(pts) >= len(key_pts):
            continue
        if _fits(pts, key_pts):
            candidates.append((len(pts), color, pts))
    if not candidates:
        return [row[:] for row in grid]
    _, _, target = max(candidates, key=lambda o: o[0])
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = key_color
    return out
